package e.e.a;
import android.app.*;import android.content.*;import android.view.*;import android.widget.*;import org.json.*;import java.util.*;
/** Each target owns its draft. Switching targets never discards an edit. */
public final class FilterEditor110 {
 static final WeakHashMap<Context,String[]> SOURCES=new WeakHashMap<>();
 static final WeakHashMap<Context,Object> ROWS=new WeakHashMap<>();
 public static void prepare(Context c,String owner,Object row){ROWS.put(UiDialogs.owner(c),row);}
 public static void confirm(Context c,String owner){Object row=ROWS.remove(UiDialogs.owner(c));if(row==null){ContentFilter.confirmOwner(c,owner);return;}confirm(c,owner,row);}
 public static void confirm(Context c,String owner,Object row){Context host=UiDialogs.owner(c);SOURCES.put(host,new String[]{ListActions.value(row,"title"),owner});OwnerNg194.confirmOwner(c,owner,row);}
 static String tr(Context c,String j,String e,String z){return PanelUi.tr(c,j,e,z);}
 public static void edit(Activity a,JSONArray data,JSONObject original,int initial,Runnable refresh){Context c=PlaybackSession.dialogContext(a);JSONObject o=original==null?new JSONObject():original;int[] category={Math.max(0,Math.min(1,o.optInt("category",initial)))};String[] source=SOURCES.remove(a),draft={"",""};if(source!=null){draft[0]=source[0];draft[1]=source[1];}draft[category[0]]=o.optString("value",draft[category[0]]);LinearLayout box=PanelUi.column(c);UiDialogs.insetContent(box);CheckBox enabled=new CheckBox(c);enabled.setText(tr(c,"有効","Enabled","啟用"));enabled.setChecked(o.optBoolean("enabled",true));PanelUi.tint(enabled);box.addView(enabled);LinearLayout targets=new LinearLayout(c);Button title=PanelUi.button(c,FilterUi110.category(c,0)),owner=PanelUi.button(c,FilterUi110.category(c,1));targets.addView(title,new LinearLayout.LayoutParams(0,PanelUi.dp(c,44),1));targets.addView(owner,new LinearLayout.LayoutParams(0,PanelUi.dp(c,44),1));box.addView(targets);RadioGroup modes=new RadioGroup(c);String[] keys={"partial","exact","regex"};for(int n=0;n<3;n++){RadioButton b=new RadioButton(c);b.setId(100+n);b.setText(FilterUi110.mode(c,keys[n]));PanelUi.tint(b);modes.addView(b);if(keys[n].equals(o.optString("mode","partial")))b.setChecked(true);}box.addView(modes);EditText value=new EditText(c);value.setTag("nicoid-managed-input");value.setText(draft[category[0]]);value.setMaxLines(3);value.setHint(tr(c,"NGワード","Blocked keyword","封鎖關鍵字"));box.addView(value);Button clear=PanelUi.button(c,tr(c,"入力を消去","Clear input","清除輸入"));clear.setOnClickListener(v->value.setText(""));box.addView(clear);EditText id=new EditText(c);id.setTag("nicoid-managed-input");id.setSingleLine(true);id.setInputType(2);id.setText(o.optString("userId"));id.setHint(tr(c,"投稿者ID（任意）","Uploader ID (optional)","投稿者ID（選填）"));box.addView(id);Runnable draw=()->{title.setTextColor(category[0]==0?UiDialogs.accent(c):PanelUi.ink(c));owner.setTextColor(category[0]==1?UiDialogs.accent(c):PanelUi.ink(c));id.setVisibility(category[0]==1?View.VISIBLE:View.GONE);};for(int n=0;n<2;n++){final int at=n;(n==0?title:owner).setOnClickListener(v->{draft[category[0]]=value.getText().toString();category[0]=at;value.setText(draft[at]);draw.run();});}draw.run();ScrollView scroll=new ScrollView(c);scroll.addView(box);AlertDialog d=UiDialogs.builder(c).setTitle(tr(c,original==null?"NG登録":"NG編集",original==null?"Add NG rule":"Edit NG rule",original==null?"新增 NG 規則":"編輯 NG 規則")).setView(scroll).setPositiveButton(android.R.string.ok,null).setNegativeButton(android.R.string.cancel,null).create();PlaybackSession.showForm(d);d.getButton(-1).setOnClickListener(v->{String text=value.getText().toString(),user=id.getText().toString().trim(),mode=keys[Math.max(0,modes.getCheckedRadioButtonId()-100)];if(text.trim().isEmpty()){value.setError(tr(c,"文字を入力してください","Enter a value","請輸入文字"));return;}if(category[0]==1&&!user.isEmpty()&&!user.matches("[0-9]+")){id.setError(tr(c,"数字で入力してください","Enter digits","請輸入數字"));return;}try{if(mode.equals("regex"))java.util.regex.Pattern.compile(text);o.put("category",category[0]).put("value",text).put("mode",mode).put("enabled",enabled.isChecked());if(category[0]==1)o.put("userId",user);else o.remove("userId");if(original==null){o.put("date",System.currentTimeMillis());data.put(o);}ContentFilter.save(a,data);d.dismiss();refresh.run();}catch(java.util.regex.PatternSyntaxException e){value.setError(tr(c,"正規表現が不正です","Invalid regular expression","正規表示式無效"));}catch(JSONException e){android.util.Log.w("nicoid-filter","Cannot save rule",e);}});}
}
